const item=$json||{};
const headers=(item.headers&&typeof item.headers==='object')?item.headers:{};
const raw=(item.body&&typeof item.body==='object')?item.body:item;
let vars={};
try{vars=(typeof $vars!=='undefined'&&$vars)?$vars:{};}catch(e){vars={};}
const expectedSecret=String(vars.OAK_WEBHOOK_SECRET||'').trim();
const suppliedSecret=String(headers['x-oak-webhook-secret']||headers['X-Oak-Webhook-Secret']||'').trim();
const authMode=expectedSecret?'enforced':'open_no_secret_configured';
const authOk=expectedSecret?(suppliedSecret===expectedSecret):true;
const clean=(v)=>String(v==null?'':v).trim();
const email=clean(raw.email).toLowerCase();
const emailValid=/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email);
const emailDomain=emailValid?email.split('@').pop():'';
const personal=['gmail.com','googlemail.com','outlook.com','hotmail.com','live.com','yahoo.com','icloud.com','proton.me','protonmail.com'];
const suppliedDomain=clean(raw.company_domain).toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').split('/')[0];
const inferredDomain=!suppliedDomain&&emailValid&&personal.indexOf(emailDomain)<0?emailDomain:'';
const companyDomain=suppliedDomain||inferredDomain;
const suppliedCompany=clean(raw.company_name);
const inferredCompany=!suppliedCompany&&companyDomain?companyDomain.split('.')[0].replace(/[-_]+/g,' ').replace(/\b\w/g,c=>c.toUpperCase()):'';
const companyName=suppliedCompany||inferredCompany;
const eventId=clean(raw.event_id)||'oak-live-event-2026';
const scanId=clean(raw.scan_id);
const first=clean(raw.first_name);const last=clean(raw.last_name);
const notes=clean(raw.notes_from_booth);
function hash(text){let h=2166136261;for(let i=0;i<text.length;i++){h^=text.charCodeAt(i);h=Math.imul(h,16777619);}return(h>>>0).toString(16);}
const missing=[];
if(!emailValid)missing.push('email');
if(!first&&!last)missing.push('name');
if(!companyName&&!companyDomain)missing.push('company');
if(!clean(raw.job_title))missing.push('job_title');
if(!notes)missing.push('notes_from_booth');
const fatal=[];
if(!scanId)fatal.push('scan_id');
if(!emailValid&&!first&&!last&&!companyName)fatal.push('person_identity');
return{json:{scan_id:scanId,event_id:eventId,event_person_key:eventId+'|'+(emailValid?email:('scan:'+scanId)),first_name:first,last_name:last,full_name:[first,last].filter(Boolean).join(' ')||email||'Unknown visitor',email:emailValid?email:'',email_valid:emailValid,email_domain:emailDomain,personal_email:emailValid&&personal.indexOf(emailDomain)>=0,company_domain:companyDomain,company_domain_source:suppliedDomain?'scanner':(inferredDomain?'email_domain':'unknown'),job_title:clean(raw.job_title),company_name:companyName,company_name_source:suppliedCompany?'scanner':(inferredCompany?'email_domain':'unknown'),scanned_at:clean(raw.scanned_at)||new Date().toISOString(),notes_from_booth:notes,notes_hash:hash(notes.toLowerCase()),auth_ok:authOk,auth_mode:authMode,valid:fatal.length===0,validation_errors:fatal,data_quality:{missing_fields:missing,complete:missing.length===0,can_sync_contact:emailValid,can_enrich_company:Boolean(companyDomain||companyName)},normalized_at:new Date().toISOString()}};

const d=$('Evaluate ICP Policy').first().json;
const prior=($json&&$json.event_person_key)?$json:null;
const n=Number((prior&&prior.scan_count)||0)+1;
const repeat=n>1;
const classChanged=Boolean(repeat&&prior.last_classification&&prior.last_classification!==d.classification);
const notesChanged=Boolean(repeat&&prior.last_notes_hash&&prior.last_notes_hash!==d.notes_hash);
const material=Boolean(classChanged||notesChanged);
let history=[];
if(prior&&prior.scan_history_json){try{const h=JSON.parse(prior.scan_history_json);if(Array.isArray(h))history=h;}catch(e){history=[];}}
if(!history.length&&prior&&prior.notes_from_booth){history=[{scan_id:null,scanned_at:prior.last_scanned_at||prior.first_scanned_at||null,notes:String(prior.notes_from_booth||''),classification:prior.last_classification||null,score:prior.last_score==null?null:Number(prior.last_score),job_title:prior.job_title||null}];}
const previous=history.length?history[history.length-1]:null;
const entry={scan_id:d.scan_id,scanned_at:d.scanned_at,notes:String(d.notes_from_booth||''),classification:d.classification,score:Number(d.score||0),job_title:d.job_title||null,recorded_at:new Date().toISOString()};
const nextHistory=history.concat([entry]).slice(-20);
const mode=repeat?(classChanged?'repeat_escalation':'repeat_thread'):'first_scan';
const repeatReason=repeat?(classChanged?('tier changed from '+String(prior.last_classification||'unknown').replace(/_/g,' ')+' to '+String(d.classification).replace(/_/g,' ')):(notesChanged?'new booth notes since the last scan':'same booth notes as the last scan')):null;
return[{json:{...d,repeat_scan:repeat,scan_count:n,prior_classification:(prior&&prior.last_classification)||null,rep_override:(prior&&prior.override_classification)||null,rep_override_reason:(prior&&prior.downgrade_reason)||null,rep_override_by:(prior&&prior.last_action_by)||null,rep_override_at:(prior&&prior.last_action_at)||null,rep_excluded_from_outreach:Boolean(prior&&prior.exclude_from_outreach===true),classification_changed:classChanged,notes_changed:notesChanged,material_change:material,notification_mode:mode,repeat_reason:repeatReason,repeat_indicator:repeat?('RETURNING VISITOR — scan #'+n):null,previous_scan:previous,previous_notes_from_booth:previous?previous.notes:null,scan_history:nextHistory,scan_history_json:JSON.stringify(nextHistory),previous_slack_channel:(prior&&prior.last_slack_channel)||null,previous_slack_ts:(prior&&prior.last_slack_ts)||null,first_scanned_at:(prior&&prior.first_scanned_at)||d.scanned_at}}];

const v=$('Build Visitor Context').first().json;
const c=($json&&$json.company_domain)?$json:null;
const fresh=Boolean(c&&c.expires_at&&new Date(c.expires_at).getTime()>Date.now()&&String(c.status||'')==='complete');
let enrichment={};let evidence=[];
if(fresh){
  try{enrichment=JSON.parse(c.payload_json||'{}');}catch(e){enrichment={};}
  try{evidence=JSON.parse(c.evidence_json||'[]');}catch(e){evidence=[];}
}
let classification=v.classification;
let competitorStatus=v.competitor_status;
let routing=Object.assign({},v.routing||{});
const reasons=(v.decision_reasons||[]).slice();
if(competitorStatus!=='confirmed'&&enrichment.possible_competitor===true&&classification!=='out_of_scope'&&classification!=='competitor_intel'){
  competitorStatus='possible';
  classification='needs_review';
  const nr=((v.policy||{}).notifications||{}).needs_review||{};
  routing={channel:String(nr.channel||'booth-review'),owner_dm:nr.owner_dm===true,mention:false};
  reasons.push('Cached public-site language matches competitor terms, so a human decides before any outreach.');
}
const crmContext={lookup_status:'pending',existing_contact:null,owner_id:null,open_deal:null,customer_status:null};
const why=reasons.join(' ');
const dontSay=(v.competitor_dont_say||['Do not discuss ConnectAny internals.']).join(' ');
const action=classification==='competitor_intel'?(dontSay+' Capture what they ask about and route to competitive intelligence.'):classification==='out_of_scope'?'Qualify politely, keep the CRM record, and do not escalate to sales.':'Qualify the environment first. Position: '+(v.persona_angle||'');
return[{json:{...v,classification,competitor_status:competitorStatus,routing,decision_reasons:reasons,enrichment_cache_hit:fresh,needs_company_enrichment:!fresh,company_enrichment:enrichment,company_evidence:evidence,crm_context:crmContext,alert:{headline:v.repeat_scan?v.repeat_indicator:(classification.toUpperCase()+' — '+v.full_name),who:v.full_name+' — '+v.job_title+' at '+v.company_name,why_now:why,what_to_do:action,score:v.score,score_breakdown:v.score_breakdown,crm_context:crmContext,evidence:[...(v.urgency_evidence||[]),...evidence],repeat_scan:v.repeat_scan,scan_count:v.scan_count,delivery_mode:v.notification_mode,routing}}}];

const p=$('Build Alert Package').first().json;
const {policy,...payload}=p;
return[{json:payload}];

const x=$('Reason with AI').first().json||{};
let p={};
try{p=JSON.parse((($('Load Gate Policy').first()||{}).json||{}).document_json||'{}');}catch(e){p={};}
if(!p||!p.notifications)p=x.policy||{};
const notif=p.notifications||{};
const mentionTiers=notif.mention_tiers||['tier_1'];
let classification=String(x.classification||'needs_review');
let routing=Object.assign({},x.routing||{});
const reasons=(x.decision_reasons||[]).filter(r=>!/^null employees/i.test(String(r)));
const trace=(x.decision_trace||[]).filter(t=>!/^null employees/i.test(String((t||{}).detail||'')));
let rule=String(x.rule_summary||'');
const route=(key,fallback)=>{const n=notif[key]||{};routing={channel:String(n.channel!==undefined?n.channel:fallback),owner_dm:n.owner_dm===true,mention:mentionTiers.indexOf(key)>=0};};
const sizeUnverified=x.company_size_band==='unknown';
// 05 may lift a needs_review or out_of_scope lead when it resolves an ambiguous title, without
// knowing why the lead was parked. A possible competitor stays with a human, and a SaaS-only or
// single-cloud disqualifier found on the company's own site keeps workflow 04's out_of_scope call.
const possibleCompetitor=x.competitor_status==='possible';
const siteDisq=(((x.company_enrichment||{}).disqualifier_signals)||[]).filter(Boolean);
if(x.competitor_status==='confirmed'&&x.competitor){
  classification='competitor_intel';route('competitor_intel','competitive-intel');routing.mention=false;
  rule='Competitor: '+(x.competitor.name||'active competitor')+' employee';
}else if(x.company_size_band==='disqualified_under_500'&&!possibleCompetitor){
  classification='out_of_scope';route('out_of_scope','booth-out-of-scope');routing.mention=false;
  rule='Out of scope: under 500 employees';
}else if(siteDisq.length&&!possibleCompetitor&&classification!=='out_of_scope'&&classification!=='competitor_intel'){
  classification='out_of_scope';route('out_of_scope','booth-out-of-scope');routing.mention=false;
  rule='Out of scope: '+siteDisq[0];
  const why='Public evidence indicates '+siteDisq.join(', ')+'.';
  if(!reasons.includes(why))reasons.push(why);
  const detail='Final deterministic gate kept the lead out of scope: the company website shows '+siteDisq.join(', ')+', which an AI persona read cannot lift.';
  if(!reasons.includes(detail)){reasons.push(detail);trace.push({code:'environment_disqualifier_final_gate',detail,source:'deterministic_rule'});}
}else if(x.company_size_band==='review_500_999'&&classification!=='out_of_scope'){
  classification='needs_review';route('needs_review','booth-review');routing.mention=false;
  rule='Review: '+String(x.persona||'persona').toUpperCase()+' + 500–999 employees';
  const detail='Final deterministic gate kept the lead in review because 500–999 employees is below the qualified 1,000+ threshold.';
  if(!reasons.includes(detail)){reasons.push(detail);trace.push({code:'company_500_999_final_gate',detail,source:'deterministic_rule'});}
}else if(possibleCompetitor&&classification!=='needs_review'){
  classification='needs_review';route('needs_review','booth-review');routing.mention=false;
  rule='Review: possible competitor';
  const detail='Final deterministic gate kept the lead in review: it is flagged as a possible competitor, and a human confirms that before any outreach.';
  if(!reasons.includes(detail)){reasons.push(detail);trace.push({code:'possible_competitor_final_gate',detail,source:'deterministic_rule'});}
}else if(classification==='out_of_scope'){
  route('out_of_scope','booth-out-of-scope');routing.mention=false;
}else{
  route(classification,classification==='tier_1'?'booth-hot':(classification==='matched'?'booth-matched':'booth-review'));
  if(!rule){const urg=(x.urgency_evidence||[])[0];rule=classification==='tier_1'?'Tier 1: '+String(x.persona||'persona').toUpperCase()+' + '+String((urg&&urg.type)||'verified urgency').replace(/_/g,' '):classification.replace(/_/g,' ')+': '+String(x.persona||'other').toUpperCase();}
  if(sizeUnverified&&x.persona&&x.persona!=='other'){
    const src=String(((x.company_enrichment||{}).employees_source)||'not_established').replace(/_/g,' ');
    const detail='Headcount could not be established from booth notes, HubSpot, the official site or identity-aligned public search ('+src+'). The tier stands on persona and trigger, and the alert asks the rep to confirm 1,000+ at the booth.';
    if(!reasons.includes(detail)){reasons.push(detail);trace.push({code:'company_size_unverified_confirm_at_booth',detail,source:'deterministic_rule'});}
    if(rule.indexOf('headcount to confirm')<0)rule=rule+' (headcount to confirm)';
  }
}
// A rep's triage press in workflow 06 (Promote, Matched, Not a fit, False alarm) is carried forward
// on a re-scan of the same badge at the same event. It is the last word on classification. The one
// exception is Not a fit: if the CRM or the visitor themselves (confidence >= 0.9) now put the
// company in the qualified 1,000+ band, neither side wins silently and a human sees both.
const ovr=String(x.rep_override||'').trim();
let repOverrideApplied=false;let repOverrideContradicted=false;
if(ovr){
  const ovrLabel=ovr.replace(/_/g,' ');
  const ovrReason=String(x.rep_override_reason||'').trim();
  const ovrBy=String(x.rep_override_by||'').trim();
  const ovrAt=String(x.rep_override_at||'').trim();
  const who=ovrBy||'A rep';
  const when=ovrAt?(' on '+ovrAt):'';
  const because=ovrReason?(' Reason given: '+ovrReason.replace(/[. ]+$/,'')+'.'):'';
  if(ovr===classification){
    const detail=who+' had already marked this lead '+ovrLabel+when+', and the deterministic gates reached the same decision on this re-scan.'+because;
    if(!reasons.includes(detail))reasons.push(detail);
    repOverrideApplied=true;
  }else{
    const er=x.employee_resolution||{};
    const contradicted=ovr==='out_of_scope'&&Number(er.confidence||0)>=0.9&&String(x.company_size_band||'')==='qualified_1000_plus';
    if(!contradicted){
      classification=ovr;route(ovr,ovr==='out_of_scope'?'booth-out-of-scope':'booth-review');routing.mention=false;
      rule='Rep override: '+ovrLabel+(ovrReason?(' - '+ovrReason):'');
      const detail=who+' overrode this lead to '+ovrLabel+when+'. No higher-confidence source contradicts that call, so it stands on this re-scan.'+because;
      if(!reasons.includes(detail))reasons.push(detail);
      trace.push({code:'rep_override_honoured',detail,source:'rep_override'});
      repOverrideApplied=true;
    }else{
      const empRaw=er.employees;
      const empNum=(empRaw===null||empRaw===undefined||empRaw==='')?null:Number(empRaw);
      const empTxt=(empNum===null||!isFinite(empNum))?'a qualifying headcount':empNum.toLocaleString()+' employees';
      const empSrc=String(er.source||'unknown source').replace(/_/g,' ');
      const empConf=Math.round(Number(er.confidence||0)*100);
      classification='needs_review';route('needs_review','booth-review');routing.mention=false;
      rule='Conflict: rep marked this '+ovrLabel+', but '+empTxt+' from '+empSrc+' qualifies the company';
      const detail=who+' marked this lead '+ovrLabel+when+'.'+because+' A higher-confidence source now contradicts that: '+empTxt+' from '+empSrc+' at '+empConf+'% confidence puts the company in the qualified 1,000+ band. Neither side wins silently - a human decides.';
      if(!reasons.includes(detail))reasons.push(detail);
      trace.push({code:'rep_override_contradicted',detail,source:'rep_override'});
      repOverrideContradicted=true;
    }
  }
}
return[{json:{...x,classification,routing,decision_reasons:reasons,decision_trace:trace,rule_summary:rule,decision_basis:Object.assign({},x.decision_basis||{},{final_deterministic_gate:true,gate_policy_version:p.version||null,unknown_size_requires_review:false,unknown_size_confirm_at_booth:sizeUnverified,rep_override_applied:repOverrideApplied,rep_override_value:ovr||null,rep_override_contradicted:repOverrideContradicted})}}];

// Both branches of "Can Sync Contact?" land here, so the ledger always reaches
// "complete" - even for a scan with no email, where the HubSpot sync is skipped.
// With an email the sync ran and its return value is the richest package.
// Without one it never ran, so the pre-CRM enriched payload is the final package.
let pkg = null;
try { const s = $('Sync to HubSpot').first().json; if (s && s.scan_id) pkg = s; } catch (e) { pkg = null; }
if (!pkg) { const i = $input.first().json; if (i && i.scan_id) pkg = i; }
if (!pkg) { try { const r = $('Restore Enriched Payload').first().json; if (r && r.scan_id) pkg = r; } catch (e) { pkg = null; } }
if (!pkg) { pkg = $input.first().json; }
return [{ json: pkg }];
